// Получаем число из inject
const inputNumber = msg.payload;

// Массив с числами для примера
let numbers = [1, 2, 3, 4, 5];

// Объект с информацией
const info = {
    student: "Кучинская",
    lab: "lab2",
    task: "2.2 function"
};

// Проверяем входное значение через if/else
let category;
if (inputNumber > 3) {
    category = "большое";
} else {
    category = "маленькое";
}

// Считаем сумму чисел в массиве через цикл for
let sum = 0;
for (let i = 0; i < numbers.length; i++) {
    sum = sum + numbers[i];
}

// Возвращаем объект с полем payload
msg.payload = {
    input: inputNumber,
    category: category,
    arraySum: sum,
    arrayLength: numbers.length,
    info: info
};

return msg;
